class Recipe {
    constructor(title, servings, ingredients) {
        this.title = title;
        this.servings = servings;
        this.ingredients = ingredients;
    }

    scale(newServings) {
        const factor = newServings / this.servings;
        return new Recipe(
            this.title,
            newServings,
            this.ingredients.map(([name, amount]) => [name, amount * factor]),
        );
    }

    print() {
        console.log(`${this.title} (${this.servings} porsiya)`);
        for (const [name, amount] of this.ingredients) {
            console.log(`- ${name}: ${amount}`);
        }
    }
}

const plov = new Recipe("Osh", 2, [["guruch (g)", 300], ["sabzi (g)", 250], ["go'sht (g)", 200]]);
plov.print();
plov.scale(6).print();

class ShoppingCart {
    items = [];

    add(name, price, quantity = 1) {
        this.items.push({ name, price, quantity });
        return this;
    }

    get total() {
        return this.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
    }

    totalWithDiscount(percent) {
        return this.total * (1 - percent / 100);
    }
}

const cart = new ShoppingCart().add("Non", 5000, 2).add("Sut", 12000).add("Tuxum", 1500, 10);
console.log(cart.total);
console.log(cart.totalWithDiscount(10));

