class Account {
    balance = 0;

    deposit(amount) {
        this.balance += amount;
        return this;
    }

    withdraw(amount) {
        if (amount > this.balance) throw new Error("Mablag' yetarli emas");
        this.balance -= amount;
        return this;
    }
}

class SavingsAccount extends Account {
    withdrawals = 0;

    withdraw(amount) {
        if (this.withdrawals >= 2) throw new Error("Oyiga 2 martadan ko'p yechib bo'lmaydi");
        super.withdraw(amount);
        this.withdrawals++;
        return this;
    }
}

