class Emitter {
    #listeners = new Map();

    on(event, listener) {
        const list = this.#listeners.get(event) ?? [];
        list.push(listener);
        this.#listeners.set(event, list);
        return this;
    }

    emit(event, ...args) {
        const list = this.#listeners.get(event) ?? [];
        for (const listener of list) listener(...args);
        return list.length;
    }
}

