        this.#min = min;
        this.#max = max;
    }

    get min() {
        return this.#min;
    }

    get max() {
        return this.#max;
    }

    includes(n) {
        return n >= this.#min && n <= this.#max;
    }

    expand(by) {
        return new Range(this.#min - by, this.#max + by);
    }
}

