function describe(value) {
    if (value === null) return "null";
    if (typeof value !== "object" && typeof value !== "function") return typeof value;
    if (Array.isArray(value)) return "massiv (" + value.length + " ta element)";
    if (typeof value === "function") return /^class\s/.test(Function.prototype.toString.call(value)) ? "sinf" : "funksiya";
    if (value instanceof Date) return "sana";
    if (value instanceof Map || value instanceof Set) return value.constructor.name + " (size " + value.size + ")";
    if (typeof value.then === "function") return "thenable";
    const proto = Object.getPrototypeOf(value);
    if (proto === null) return "prototipsiz obyekt";
    return proto === Object.prototype ? "oddiy obyekt" : value.constructor.name + " nusxasi";
}

class Student {}
const samples = [null, 5, "a", [1, 2], () => {}, Student, new Date(0), new Map([[1, 2]]), Promise.resolve(), {}, Object.create(null), new Student()];
for (const sample of samples) {
    console.log(describe(sample));
}

class ValidationError extends Error {}

function classify(fn) {
    try {
        fn();
        return "xato yo'q";
    } catch (err) {
        if (err instanceof ValidationError) return "tekshiruv xatosi: " + err.message;
        if (err instanceof TypeError) return "tur xatosi";
        if (err instanceof RangeError) return "diapazon xatosi";
        if (err instanceof Error) return "boshqa xato: " + err.name;
        return "xato emas: " + String(err);
    }
}

console.log(classify(() => { throw new ValidationError("email kerak"); }));
console.log(classify(() => null.x));
console.log(classify(() => new Array(-1)));
console.log(classify(() => JSON.parse("{")));
console.log(classify(() => { throw "matn"; }));
console.log(classify(() => 1 + 1));
